#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>

static PyObject* hungarian(PyObject* self, PyObject* args) {
    PyArrayObject* cost_arr;
    if (!PyArg_ParseTuple(args, "O", &cost_arr)) return NULL;
    if (!PyArray_Check(cost_arr)) { PyErr_SetString(PyExc_TypeError, "need ndarray"); return NULL; }
    cost_arr = (PyArrayObject*)PyArray_FROM_OTF((PyObject*)cost_arr, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (cost_arr == NULL) return NULL;
    npy_intp n = PyArray_DIM(cost_arr, 0);
    double* cost = (double*)PyArray_DATA(cost_arr);

    npy_intp* p = malloc((n+1)*sizeof(npy_intp));
    npy_intp* way = malloc((n+1)*sizeof(npy_intp));
    double* u = calloc(n+1, sizeof(double));
    double* v = calloc(n+1, sizeof(double));
    double* minv = malloc((n+1)*sizeof(double));
    unsigned char* used = malloc((n+1)*sizeof(unsigned char));
    if (!p || !way || !u || !v || !minv || !used) { PyErr_NoMemory(); return NULL; }

    const double INF = 1e300;

    for (npy_intp i = 1; i <= n; i++) {
        p[0] = i;
        npy_intp j0 = 0;
        for (npy_intp j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        while (1) {
            used[j0] = 1;
            npy_intp i0 = p[j0];
            double delta = INF;
            npy_intp j1 = 0;
            for (npy_intp j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = cost[(i0-1)*n + (j-1)] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (npy_intp j = 0; j <= n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else { minv[j] -= delta; }
            }
            j0 = j1;
            if (p[j0] == 0) break;
        }
        while (1) {
            npy_intp j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
            if (j0 == 0) break;
        }
    }

    // result: res[i] = column assigned to row i
    npy_intp dims[1] = {n};
    PyArrayObject* res = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_INTP);
    npy_intp* resdata = (npy_intp*)PyArray_DATA(res);
    for (npy_intp j = 1; j <= n; j++) {
        resdata[p[j]-1] = j-1;
    }

    free(p); free(way); free(u); free(v); free(minv); free(used);
    Py_DECREF(cost_arr);
    return (PyObject*)res;
}

static PyMethodDef methods[] = {
    {"hungarian", hungarian, METH_VARARGS, "Hungarian algorithm"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "hung", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_hung(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
